<script setup>
import {ref,computed,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useDraftGuard} from '../../composables/useDraftGuard.js'
import {notify} from '../../composables/feedback.js'
import FormField from '../../components/FormField.vue'
import {clone} from './resourceUi.js'
const formElement=ref();const r=useIrrigation(),route=useRoute(),router=useRouter(),draft=ref(null),initial=ref(''),errors=ref({}),failure=ref(''),busy=ref(false),sourceChanged=ref(false)
const creating=computed(()=>route.path==='/fields/new'),source=computed(()=>(r.state.entities.Field??[]).find(f=>f.fieldId===route.params.id))
watch(()=>[route.params.id,creating.value],()=>{draft.value=source.value?clone(source.value):creating.value?{name:'',code:'',status:'ENABLED',areaMu:null,location:[null,null],soilType:'',managerId:'',farmId:r.state.user?.farmId}:null;initial.value=JSON.stringify(draft.value);sourceChanged.value=false},{immediate:true})
watch(()=>source.value?.version,version=>{if(draft.value?.fieldId&&version!==draft.value.version)sourceChanged.value=true})
const guard=useDraftGuard(()=>JSON.stringify(draft.value)!==initial.value)
const soils=computed(()=>[...new Set((r.state.entities.Field??[]).map(f=>f.soilType))]),users=computed(()=>(r.state.entities.User??[]).filter(u=>u.status==='ENABLED'))
const allowed=computed(()=>r.can(creating.value?'FIELD_CREATE':'FIELD_UPDATE',source.value))
function back(){router.push(creating.value?'/fields':'/fields/'+route.params.id)}
async function save(){busy.value=true;failure.value='';errors.value={};try{const result=await r.commit(creating.value?'FIELD_CREATE':'FIELD_UPDATE',draft.value,{expectedVersion:draft.value.version,clientRequestId:crypto.randomUUID()});initial.value=JSON.stringify(draft.value);guard.markClean();notify('保存成功');router.push('/fields/'+result.entityId)}catch(e){errors.value=e.fieldErrors??{};failure.value=e.message;await nextTick();formElement.value?.querySelector('[aria-invalid=true]')?.focus()}finally{busy.value=false}}
const marker=computed(()=>({x:Math.max(70,Math.min(1120,600+(Number(draft.value?.location?.[0])-115.56)*8000)),y:Math.max(40,Math.min(180,95-(Number(draft.value?.location?.[1])-37.54)*6000))}))
</script>
<template><div v-if="draft" class="page-stack field-edit"><div class="back-row"><button class="btn" @click="back">〈　返回</button></div><p v-if="sourceChanged" class="inline-error" role="status">来源田块已更新，当前草稿已保留。请返回后重新打开并核对最新版本。</p><form ref="formElement" @submit.prevent="save"><section class="panel"><h2 class="panel-title">田块基本资料</h2><div class="form-grid"><FormField label="田块编号"><input :value="draft.code||'保存后自动生成'" readonly/></FormField><FormField label="田块名称" :error="errors.name" required hide-required-marker><input v-model="draft.name" :aria-invalid="!!errors.name" :readonly="!allowed"/></FormField><FormField label="启用状态" :error="errors.status"><select v-model="draft.status" :aria-invalid="!!errors.status" :disabled="!allowed"><option value="ENABLED">启用</option><option value="DISABLED">停用</option></select></FormField><FormField label="版本"><input :value="draft.version??'未创建'" readonly/></FormField></div></section><section class="panel"><h2 class="panel-title">位置面积</h2><div class="form-grid"><FormField label="面积（亩）" :error="errors.areaMu" required hide-required-marker><input v-model.number="draft.areaMu" :aria-invalid="!!errors.areaMu" type="number" step="0.1" :readonly="!allowed"/></FormField><FormField label="经度" :error="errors.location" required hide-required-marker><input v-model.number="draft.location[0]" :aria-invalid="!!errors.location" type="number" step="any" :readonly="!allowed"/></FormField><FormField label="纬度" :error="errors.location" required hide-required-marker><input v-model.number="draft.location[1]" :aria-invalid="!!errors.location" type="number" step="any" :readonly="!allowed"/></FormField></div></section><section class="panel"><h2 class="panel-title">土壤与负责人</h2><div class="form-grid"><FormField label="土壤类型" :error="errors.soilType" required hide-required-marker><select v-model="draft.soilType" :aria-invalid="!!errors.soilType" :disabled="!allowed"><option value="">请选择</option><option v-for="s in soils" :key="s">{{s}}</option></select></FormField><FormField label="负责人" :error="errors.managerId" required hide-required-marker><select v-model="draft.managerId" :aria-invalid="!!errors.managerId" :disabled="!allowed"><option value="">请选择</option><option v-for="u in users" :key="u.userId" :value="u.userId">{{u.name}}</option></select></FormField></div></section><section class="panel"><h2 class="panel-title">位置示意图</h2><svg class="location-map" viewBox="0 0 1200 216" role="img" :aria-label="'位置 '+draft.location.join(',')"><defs><pattern id="coordinate-grid" width="79" height="52" patternUnits="userSpaceOnUse"><path d="M79 0H0V52" fill="none" stroke="#b4d3c3" stroke-dasharray="5 3"/></pattern></defs><rect width="1200" height="216" fill="#ecf6ec"/><rect width="1200" height="216" fill="url(#coordinate-grid)"/><path :transform="`translate(${marker.x},${marker.y})`" d="M0 18C-25-12 22-25 12 0Z" fill="#178064"/><circle :cx="marker.x+3" :cy="marker.y-3" r="4" fill="white"/><text :x="marker.x+24" :y="marker.y+32">{{draft.location.join('，')}}</text><text x="1170" y="22">N</text><path d="M1174 28l-9 20 9-5 9 5Z" fill="#38555a"/></svg></section><p v-if="failure" class="inline-error" role="alert">{{failure}}</p><div class="form-actions"><button class="btn btn-primary" :disabled="busy||!allowed">{{busy?'保存中…':'保存'}}</button><button type="button" class="btn" :disabled="busy" @click="back">取消</button><button type="button" class="btn" :disabled="busy" @click="draft=JSON.parse(initial);errors={};failure=''">重置</button></div></form></div><div v-else class="panel empty-state">记录不存在 <button class="btn" @click="router.push('/fields')">返回田块列表</button></div></template>
<style scoped>.field-edit form{display:flex;flex-direction:column;gap:16px}.field-edit .panel{padding:13px 23px 17px}.field-edit :deep(.form-field){display:grid;grid-template-columns:120px 1fr;align-items:center;gap:16px}.field-edit :deep(.error-text){grid-column:2}.field-edit .form-grid{gap:12px 54px}.field-edit .panel-title{margin-bottom:12px;font-size:21px}.location-map{width:100%;height:219px;border:1px solid #d4e5d9;border-radius:3px}.field-edit .form-actions{background:white;margin:2px -22px -22px -20px;border-top:1px solid #d5e0e2;padding:17px}.field-edit :deep(.form-field-label){font-size:16px;color:#223e47}.field-edit :deep(.required){display:none}
</style>
